#include <memory>
#include <string>
#include <utility>

struct Circle
{
    double radius{};
    double area() const { return 3.14159 * radius * radius; }
    std::string name() const { return "circle"; }
};

struct Square
{
    double side{};
    double area() const { return side * side; }
    std::string name() const { return "square"; }
};

class AnyShape
{
public:
    template <typename T>
    AnyShape(T shape) : m_self{ std::make_unique<Model<T>>(std::move(shape)) } {}

    AnyShape(const AnyShape& other) : m_self{ other.m_self->clone() } {}
    AnyShape(AnyShape&&) noexcept = default;

    AnyShape& operator=(const AnyShape& other)
    {
        if (this != &other)
        {
            m_self = other.m_self->clone();
        }
        return *this;
    }
    AnyShape& operator=(AnyShape&&) noexcept = default;

    double area() const { return m_self->area(); }
    std::string name() const { return m_self->name(); }

private:
    struct Concept
    {
        virtual ~Concept() = default;
        virtual double area() const = 0;
        virtual std::string name() const = 0;
        virtual std::unique_ptr<Concept> clone() const = 0;
    };

    template <typename T>
    struct Model final : Concept
    {
        explicit Model(T value) : data{ std::move(value) } {}
        double area() const override { return data.area(); }
        std::string name() const override { return data.name(); }
        std::unique_ptr<Concept> clone() const override { return std::make_unique<Model>(*this); }
        T data;
    };

    std::unique_ptr<Concept> m_self{};
};

unitTests:
struct Blob { double area() const { return 42.0; } std::string name() const { return "blob"; } };

TEST("holds unrelated types") { const AnyShape a{ Circle{ 1.0 } }; const AnyShape b{ Square{ 3.0 } }; CHECK_EQ(a.name(), "circle"); CHECK_NEAR(a.area(), 3.14159, 1e-9); CHECK_EQ(b.name(), "square"); CHECK_NEAR(b.area(), 9.0, 1e-9); }
TEST("including ones it has never heard of") { const AnyShape s{ Blob{} }; CHECK_EQ(s.name(), "blob"); CHECK_NEAR(s.area(), 42.0, 1e-9); }
TEST("a vector can mix them") { const std::vector<AnyShape> shapes{ Circle{ 1.0 }, Square{ 2.0 }, Blob{} }; double total{ 0.0 }; std::string names; for (const AnyShape& s : shapes) { total += s.area(); names += s.name() + " "; } CHECK_NEAR(total, 3.14159 + 4.0 + 42.0, 1e-9); CHECK_EQ(names, "circle square blob "); }
TEST("copies are independent values") { AnyShape a{ Square{ 2.0 } }; AnyShape b{ a }; a = Circle{ 1.0 }; CHECK_EQ(a.name(), "circle"); CHECK_EQ(b.name(), "square"); b = a; CHECK_EQ(b.name(), "circle"); }
TEST("it is one plain, non-template type") { static_assert(!std::is_polymorphic_v<AnyShape>); static_assert(std::is_copy_constructible_v<AnyShape> && std::is_nothrow_move_constructible_v<AnyShape>); CHECK_EQ(sizeof(AnyShape), sizeof(void*)); }
TEST("no leaks") { CHECK_NO_LEAK(AnyShape a{ Circle{ 1.0 } }; AnyShape b{ a }; AnyShape c{ std::move(a) }; b = c; c = Square{ 1.0 }); }

